function countDigitOne(n) {
  let count = 0;

  for (let place = 1; place <= n; place *= 10) {
    const higher = Math.floor(n / (place * 10));
    const digit = Math.floor(n / place) % 10;
    const lower = n % place;

    count += higher * place;
    if (digit > 1) {
      count += place;
    } else if (digit === 1) {
      count += lower + 1;
    }
  }
  return count;
}

