function countDigitOne(n) {
  // Digit DP over the decimal string: walk(pos, tight) returns
  // [how many digit suffixes are allowed, how many 1s they contain in total].
  const digits = String(n).split('').map(Number);
  const memo = new Map();
  const walk = (pos, tight) => {
    if (pos === digits.length) return [1, 0];
    const key = pos * 2 + (tight ? 1 : 0);
    if (memo.has(key)) return memo.get(key);
    const limit = tight ? digits[pos] : 9;
    let numbers = 0, ones = 0;
    for (let d = 0; d <= limit; d++) {
      const [count, inner] = walk(pos + 1, tight && d === limit);
      numbers += count;
      ones += inner + (d === 1 ? count : 0);
    }
    memo.set(key, [numbers, ones]);
    return [numbers, ones];
  };
  return walk(0, true)[1];
}

