function generate(rand, size) {
  if (size === 'large') return [Math.floor(rand() * 1e9) + 1];
  const pick = rand();
  if (pick < 0.15) return [Math.floor(rand() * 12)];
  if (pick < 0.4) {
    // Close to a power of ten, where the counting rules change.
    const power = 10 ** (1 + Math.floor(rand() * 5));
    return [Math.max(0, power + Math.floor(rand() * 7) - 3)];
  }
  const digits = 1 + Math.floor(rand() * 9);
  return [Math.floor(rand() * 10 ** digits)];
}
